import{_ as i,o as a,c as t,a2 as s}from"./chunks/framework.Crpw6aS5.js";const u=JSON.parse('{"title":"H5 Access Design","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-09-h5-access-design.md","filePath":"superpowers/specs/2026-05-09-h5-access-design.md","lastUpdated":1778339295000}'),n={name:"superpowers/specs/2026-05-09-h5-access-design.md"};function o(l,e,r,d,h,c){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="h5-access-design" tabindex="-1">H5 Access Design <a class="header-anchor" href="#h5-access-design" aria-label="Permalink to &quot;H5 Access Design&quot;">​</a></h1><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Add a simple H5 access mode for personal and team use. A desktop user can enable H5 access in Settings, generate a token, expose the frontend/backend through LAN or their own reverse proxy, and open the same chat experience from a phone browser.</p><p>This is not a public multi-tenant product login system. The design intentionally keeps the first version small while avoiding accidental exposure of the existing desktop API.</p><h2 id="non-goals" tabindex="-1">Non-Goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-Goals&quot;">​</a></h2><ul><li>Do not change the default desktop/Tauri local flow.</li><li>Do not add account login, OAuth, user management, or short-lived session exchange in the first version.</li><li>Do not make every desktop-only feature mobile-first in the first version.</li><li>Do not expose unauthenticated remote API access.</li></ul><h2 id="current-context" tabindex="-1">Current Context <a class="header-anchor" href="#current-context" aria-label="Permalink to &quot;Current Context&quot;">​</a></h2><p>The desktop frontend is already a Vite SPA under <code>desktop/</code>. In non-Tauri browser mode, <code>desktop/src/lib/desktopRuntime.ts</code> accepts <code>?serverUrl=</code> and points the API client at that backend. The backend in <code>src/server/index.ts</code> can bind to a configured host and already requires auth for non-localhost hosts. The missing pieces are productized H5 settings, H5 token handling in the frontend, configurable CORS, WebSocket token support, and mobile-safe layout.</p><h2 id="product-shape" tabindex="-1">Product Shape <a class="header-anchor" href="#product-shape" aria-label="Permalink to &quot;Product Shape&quot;">​</a></h2><p>Settings gets a new <code>H5 Access</code> section:</p><ul><li>Enable/disable H5 access.</li><li>Generate a strong random token when enabling.</li><li>Show masked token with copy and regenerate actions.</li><li>Show an H5 URL that can be copied.</li><li>Allow an optional public frontend/base URL override for users running a reverse proxy.</li><li>Show a concise safety note: this is intended for LAN or self-managed reverse proxy use, and anyone with the token can operate the exposed chat surface.</li></ul><p>The H5 browser entry shows a connection screen when no token is stored:</p><ul><li>Server URL field.</li><li>Token field.</li><li>Connect button.</li><li>Clear, non-secret error messages for unreachable server, bad token, CORS block, and WebSocket failure.</li></ul><p>After connection, the phone opens the existing chat product with a mobile-optimized shell.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><h3 id="server-configuration" tabindex="-1">Server Configuration <a class="header-anchor" href="#server-configuration" aria-label="Permalink to &quot;Server Configuration&quot;">​</a></h3><p>Persist H5 settings in the existing cc-haha managed settings path (<code>~/.claude/cc-haha/settings.json</code>), preserving unknown fields and keeping the user-owned <code>~/.claude/settings.json</code> untouched:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> H5AccessSettings</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  enabled</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> boolean</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  tokenHash</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  tokenPreview</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  allowedOrigins</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[]</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  publicBaseUrl</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Store only a hash of the token. The raw token is shown only when generated or copied immediately after regeneration. If the user loses it, they regenerate it.</p><p>Server behavior:</p><ul><li>Localhost desktop mode remains unchanged.</li><li>When H5 is disabled, remote browser origins are not allowed by CORS.</li><li>When H5 is enabled, configured <code>allowedOrigins</code> can pass CORS.</li><li>Remote <code>/api/*</code>, <code>/proxy/*</code>, and <code>/ws/*</code> require <code>Authorization: Bearer &lt;h5-token&gt;</code> or a WebSocket <code>token</code> query parameter.</li><li><code>/health</code> remains useful for local desktop startup, but when the request is non-local and H5 is enabled it should return only minimal service status and no sensitive diagnostics.</li></ul><h3 id="client-runtime" tabindex="-1">Client Runtime <a class="header-anchor" href="#client-runtime" aria-label="Permalink to &quot;Client Runtime&quot;">​</a></h3><p>Extend the existing browser-mode startup:</p><ul><li>Keep Tauri mode using <code>get_server_url</code>.</li><li>In browser mode, read <code>serverUrl</code> from query string or localStorage.</li><li>Read H5 token from localStorage.</li><li>If missing or invalid, render the H5 connection screen.</li><li>Add the token to REST requests through the central API client.</li><li>Add the token to WebSocket connections with a query parameter.</li><li>Fix WebSocket URL construction so <code>https://</code> backends become <code>wss://</code>, not an invalid <code>wss</code> derived by string accident.</li></ul><h3 id="api-surface" tabindex="-1">API Surface <a class="header-anchor" href="#api-surface" aria-label="Permalink to &quot;API Surface&quot;">​</a></h3><p>First version grants token holders the same core desktop API needed for chat:</p><ul><li>sessions list/detail/messages/create/delete/rename</li><li>chat WebSocket</li><li>slash commands and inspection endpoints used by the chat UI</li><li>settings reads needed for model and permission controls</li><li>provider/model selection paths used by the composer</li></ul><p>High-risk or desktop-native surfaces should be hidden or disabled in the H5 UI unless they are already required by chat:</p><ul><li>terminal</li><li>doctor repair</li><li>native updater</li><li>native file dialogs</li><li>broad filesystem browsing</li><li>plugin, MCP, and skill management</li></ul><p>The server can still protect these with the same H5 token in the first implementation, but the UI should not present them as primary H5 workflows until mobile handling and risk review are done.</p><h2 id="mobile-ui-design" tabindex="-1">Mobile UI Design <a class="header-anchor" href="#mobile-ui-design" aria-label="Permalink to &quot;Mobile UI Design&quot;">​</a></h2><p>The H5 shell should be mobile-first without rewriting the desktop UI.</p><h3 id="layout-rules" tabindex="-1">Layout Rules <a class="header-anchor" href="#layout-rules" aria-label="Permalink to &quot;Layout Rules&quot;">​</a></h3><ul><li>Replace mobile <code>h-screen</code> usage with a <code>100dvh</code>/safe-area shell.</li><li>Add a viewport hook or CSS breakpoint around 768px.</li><li>On mobile, sidebar becomes a drawer with a backdrop instead of a fixed rail.</li><li>Main chat is a single column.</li><li>Workspace and terminal split panels are not shown as side-by-side panes on mobile; first version hides them from the mobile chat shell.</li><li>Keep desktop layout unchanged above the breakpoint.</li></ul><h3 id="chat-priority" tabindex="-1">Chat Priority <a class="header-anchor" href="#chat-priority" aria-label="Permalink to &quot;Chat Priority&quot;">​</a></h3><p>The first version optimizes:</p><ul><li>session list access</li><li>open/create session</li><li>message history</li><li>streaming assistant response</li><li>send/stop</li><li>attachments if existing browser file input works safely</li><li>permission confirmation dialogs</li><li>model and permission selectors with mobile-safe popovers</li></ul><h3 id="touch-and-typography" tabindex="-1">Touch And Typography <a class="header-anchor" href="#touch-and-typography" aria-label="Permalink to &quot;Touch And Typography&quot;">​</a></h3><ul><li>Primary icon buttons on mobile use at least 44px hit targets.</li><li>Menu rows use enough vertical padding for touch.</li><li>Body text uses a readable 16px baseline where practical.</li><li>Tiny metadata can remain smaller, but it must not be required to operate the chat.</li><li>Fixed-width popovers such as permission mode selectors become full-width-with-margin sheets on mobile.</li></ul><h2 id="error-handling" tabindex="-1">Error Handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error Handling&quot;">​</a></h2><p>H5 startup errors should be actionable:</p><ul><li>Server unreachable: show the current server URL and suggest checking LAN/reverse proxy.</li><li>Unauthorized: ask the user to re-enter token.</li><li>CORS blocked: explain that the backend has not allowed this H5 origin.</li><li>WebSocket failed: show REST health status separately from chat socket status.</li><li>H5 disabled: show that H5 access must be enabled in desktop Settings.</li></ul><p>Do not show raw secrets in diagnostics or error text.</p><h2 id="security-notes" tabindex="-1">Security Notes <a class="header-anchor" href="#security-notes" aria-label="Permalink to &quot;Security Notes&quot;">​</a></h2><ul><li>H5 access is opt-in.</li><li>Token must be generated with high entropy.</li><li>Store only a hash server-side.</li><li>Token regeneration invalidates the old token.</li><li>CORS must be explicit, not wildcard.</li><li>The default bind remains localhost.</li><li>Documentation should recommend a reverse proxy with TLS for domain access.</li><li>This feature is suitable for personal/team controlled environments, not public internet exposure without additional controls.</li></ul><h2 id="implementation-boundaries" tabindex="-1">Implementation Boundaries <a class="header-anchor" href="#implementation-boundaries" aria-label="Permalink to &quot;Implementation Boundaries&quot;">​</a></h2><p>Implementation should be split into independent lanes:</p><ol><li>Server and persistence: H5 settings, token hash, auth validation, CORS origin handling, WebSocket token handling.</li><li>Desktop settings UI: enable switch, token generation/reset/copy, URL display, safety note.</li><li>H5 browser runtime: connection screen, localStorage token/server URL, REST and WebSocket auth injection.</li><li>Mobile shell: drawer sidebar, <code>dvh</code> shell, chat column constraints, mobile popover/sheet fixes.</li><li>Tests and verification: server auth/CORS tests, API client/WebSocket tests, settings UI tests, mobile browser smoke.</li></ol><p>Each lane should avoid changing unrelated desktop behavior. Desktop/Tauri tests must remain green.</p><h2 id="verification-plan" tabindex="-1">Verification Plan <a class="header-anchor" href="#verification-plan" aria-label="Permalink to &quot;Verification Plan&quot;">​</a></h2><p>Narrow checks:</p><ul><li>Server tests for H5 enabled/disabled, good token, bad token, CORS allowed/disallowed, WebSocket token accepted/rejected.</li><li>Desktop API client tests for Authorization injection and no-token local behavior.</li><li>WebSocket client tests for <code>https -&gt; wss</code> and token query parameter.</li><li>Settings UI tests for enable/regenerate/copy state.</li><li>Mobile layout tests or browser smoke at 390x844 and 430x932.</li></ul><p>Full checks before handoff:</p><ul><li><code>cd desktop &amp;&amp; bun run test</code></li><li><code>bun run check:server</code></li><li><code>bun run check:desktop</code></li><li><code>bun run verify</code> when the targeted lanes are green or report any pre-existing quality gate blocker explicitly.</li></ul><p>Manual smoke:</p><ol><li>Start backend locally with default localhost and verify desktop still works.</li><li>Enable H5 in Settings and generate token.</li><li>Start backend bound for LAN or via a local reverse-proxy equivalent.</li><li>Open H5 URL in browser/mobile viewport, enter token, list sessions, create/open session, send a message, stop a running turn, reconnect.</li></ol><h2 id="rollout" tabindex="-1">Rollout <a class="header-anchor" href="#rollout" aria-label="Permalink to &quot;Rollout&quot;">​</a></h2><p>Ship as opt-in beta wording in Settings. Keep H5 disabled by default. The first version should document LAN and reverse-proxy setup, but should not promise production public hosting.</p>`,58)])])}const k=i(n,[["render",o]]);export{u as __pageData,k as default};
